const N4_STAGES=['words','grammar','reading','listening','review'];
const N4_STAGE_LABELS={words:'词汇认读',grammar:'句型与例句',reading:'阅读理解',listening:'听力理解',review:'单元复习'};
function cleanStudyExtras(raw){const favorite=(k)=>{if(typeof k!=='string')return false;const [kind,id,index]=k.split(':');if(kind==='word')return words.some(w=>w.id===id);const g=grammar.find(g=>g.id===id);return !!g&&(kind==='grammar'||kind==='example'&&/^\d+$/.test(index)&&Number(index)<g.examples.length);};const out={favorites:[...new Set((Array.isArray(raw.favorites)?raw.favorites:[]).filter(favorite))].slice(0,5000),n4:{units:{},cursor:N4_UNITS.some(u=>u.id===raw.n4?.cursor)?raw.n4.cursor:null,stage:N4_STAGES.includes(raw.n4?.stage)?raw.n4.stage:'words',final:{answers:{},submitted:!!raw.n4?.final?.submitted}}};for(const u of N4_UNITS){const s=raw.n4?.units?.[u.id];if(!s)continue;const ids=[...u.grammarIds,...(u.reading.ids||[u.reading.id]),...(u.listening.ids||[u.listening.id])],answers={};for(const [id,a]of Object.entries(s.answers||{})){const q=questionById(id);if(ids.includes(id)&&q&&Number.isInteger(a)&&a>=0&&a<q.options.length)answers[id]=a;}const review={};for(const [id,a]of Object.entries(s.review||{})){const q=questionById(id);if(ids.includes(id)&&q&&Number.isInteger(a)&&a>=0&&a<q.options.length)review[id]=a;}out.n4.units[u.id]={done:[...new Set((s.done||[]).filter(k=>N4_STAGES.includes(k)))],ratings:[...new Set((s.ratings||[]).filter(id=>u.wordIds.includes(id)))],answers,review,draft:String(s.draft||'').slice(0,4000)};}
for(const [id,a]of Object.entries(raw.n4?.final?.answers||{})){const q=questionById(id);if(q?.level==='N4'&&Number.isInteger(a)&&a>=0&&a<q.options.length)out.n4.final.answers[id]=a;}const day=raw.n4?.day;if(day&&N4_UNITS.some(u=>u.id===day.unit)&&Array.isArray(day.stages)&&day.stages.length>0&&day.stages.every(k=>N4_STAGES.includes(k)))out.n4.day={unit:day.unit,stages:[...new Set(day.stages)]};return out;}
function mergeStudyExtras(a,b){const x=cleanStudyExtras(a),y=cleanStudyExtras(b);b.favorites=[...new Set([...x.favorites,...y.favorites])];for(const [id,v]of Object.entries(x.n4.units)){const z=y.n4.units[id];y.n4.units[id]=z?{...z,done:[...new Set([...v.done,...z.done])],ratings:[...new Set([...v.ratings,...z.ratings])],answers:{...v.answers,...z.answers},review:{...v.review,...z.review},draft:z.draft||v.draft}:v;}if(!y.n4.cursor)y.n4.cursor=x.n4.cursor;if(!Object.keys(y.n4.final.answers).length)y.n4.final=x.n4.final;b.n4=y.n4;return b;}
